mapper.select:
SELECT c.category_id AS categoryId, c.name AS name, c.type AS type,
       SUM(t.amount) AS amount, COUNT(*) AS count
FROM transactions t
JOIN categories c ON t.category_id = c.category_id
WHERE t.user_id = #{userId}
  AND t.type = 'EXPENSE'
  AND t.occurred_at >= #{startAt}
  AND t.occurred_at < #{endAt}
GROUP BY c.category_id, c.name, c.type
ORDER BY amount DESC

SELECT insight_id, user_id, `year`, `month`, insight_type, content, created_at
FROM ai_insights
WHERE user_id = #{userId}
  AND `year` = #{year}
  AND `month` = #{month}
ORDER BY insight_id

mapper.delete:
DELETE FROM ai_insights
WHERE user_id = #{userId}
  AND `year` = #{year}
  AND `month` = #{month}
